"""Minimal fixed-fixture benchmark for the active EXPC-WLK model."""
import os
from pathlib import Path
import platform
import time
import wave
import winreg

import numpy as np

from . import cuda_guard, model_store


FIXTURE = Path(__file__).resolve().parent / "assets" / "sounds" / "stt-benchmark.wav"


class ModelUnavailable(RuntimeError):
    pass


class CudaUnavailable(RuntimeError):
    pass


def _cpu_name():
    try:
        with winreg.OpenKey(
            winreg.HKEY_LOCAL_MACHINE,
            r"HARDWARE\DESCRIPTION\System\CentralProcessor\0",
        ) as key:
            return str(winreg.QueryValueEx(key, "ProcessorNameString")[0]).strip()
    except OSError:
        return platform.processor() or "Unknown CPU"


def _gpu_name():
    try:
        from .platform.windows import gpu
        return gpu._detect_gpu()[1] or "Not detected"
    except Exception:
        return "Not detected"


def _read_fixture(path):
    with wave.open(str(path), "rb") as stream:
        channels = stream.getnchannels()
        sample_width = stream.getsampwidth()
        sample_rate = stream.getframerate()
        frames = stream.getnframes()
        payload = stream.readframes(frames)
    if sample_width != 2 or channels not in (1, 2):
        raise ValueError("Benchmark WAV must be 16-bit mono/stereo PCM")
    audio = np.frombuffer(payload, dtype="<i2").astype(np.float32)
    if channels == 2:
        audio = audio.reshape(-1, 2).mean(axis=1)
    audio /= 32768.0
    return audio, frames / sample_rate


def run(engine, metadata_root, model_root, fixture=FIXTURE):
    """Benchmark the active model without mutating the engine or configuration."""
    model_id = engine.model_key
    device = engine.device
    if model_id == "large-v3-turbo":
        available, _ = cuda_guard.probe(metadata_root)
        if device != "cuda" or not available:
            raise CudaUnavailable("CUDA is unavailable for large-v3-turbo")

    verification = model_store.verify_local_model(
        metadata_root, model_id, model_root=model_root)
    if verification["status"] != "valid":
        raise ModelUnavailable(verification["status"])

    audio, audio_seconds = _read_fixture(Path(fixture))
    model = engine.model
    load_seconds = 0.0
    loaded_for_benchmark = model is None
    if loaded_for_benchmark:
        from faster_whisper import WhisperModel
        manifest = model_store.manifest_for(metadata_root, model_id)
        source = Path(model_root) / manifest["directory"]
        started = time.perf_counter()
        model = WhisperModel(
            str(source), device=device, compute_type=engine.compute_type)
        load_seconds = time.perf_counter() - started

    started = time.perf_counter()
    segments, _ = model.transcribe(
        audio, beam_size=1, language=engine.language,
        condition_on_previous_text=False)
    transcript = "".join(segment.text for segment in segments).strip()
    inference_seconds = time.perf_counter() - started
    result = {
        "model": model_id,
        "backend": "CUDA" if device == "cuda" else "CPU",
        "cpu": _cpu_name(),
        "gpu": _gpu_name(),
        "audio_seconds": audio_seconds,
        "load_seconds": load_seconds,
        "model_was_loaded": loaded_for_benchmark,
        "inference_seconds": inference_seconds,
        "rtf": inference_seconds / audio_seconds,
        "transcript": transcript,
    }
    return result


def format_result(result, language="ru"):
    rtf = result["rtf"]
    if language == "ru":
        explanation = (
            "RTF < 1.0x — быстрее реального времени" if rtf < 1 else
            "RTF 1.0–2.0x — умеренная задержка" if rtf <= 2 else
            "RTF > 2.0x — заметная задержка"
        )
        load = (f"Загрузка модели: {result['load_seconds']:.1f} с"
                if result["model_was_loaded"] else "Загрузка модели: уже загружена")
        return (
            "EXPC-WLK Benchmark\n\n"
            f"Модель: {result['model']}\nBackend: {result['backend']}\n"
            f"CPU: {result['cpu']}\nGPU: {result['gpu']}\n{load}\n"
            f"Аудио: {result['audio_seconds']:.1f} с\n"
            f"Распознавание: {result['inference_seconds']:.1f} с\n"
            f"RTF: {rtf:.2f}x\n\n{explanation}\n"
            f"Ожидаемо: 10 секунд речи ≈ {rtf * 10:.1f} секунд обработки"
        )
    explanation = (
        "RTF < 1.0x — faster than real time" if rtf < 1 else
        "RTF 1.0–2.0x — moderate latency" if rtf <= 2 else
        "RTF > 2.0x — noticeable latency"
    )
    load = (f"Model load: {result['load_seconds']:.1f} s"
            if result["model_was_loaded"] else "Model load: already loaded")
    return (
        "EXPC-WLK Benchmark\n\n"
        f"Model: {result['model']}\nBackend: {result['backend']}\n"
        f"CPU: {result['cpu']}\nGPU: {result['gpu']}\n{load}\n"
        f"Audio: {result['audio_seconds']:.1f} s\n"
        f"Transcription: {result['inference_seconds']:.1f} s\n"
        f"RTF: {rtf:.2f}x\n\n{explanation}\n"
        f"Expected: 10 seconds of speech ≈ {rtf * 10:.1f} seconds processing"
    )


def save_result(text, user_profile=None):
    profile = user_profile or os.environ.get("USERPROFILE")
    if not profile:
        return None
    root = Path(profile)
    desktop = root / "Desktop"
    if not root or not desktop.is_dir():
        return None
    target = desktop / "EXPC-WLK-benchmark.txt"
    try:
        target.write_text(text + "\n", encoding="utf-8")
        return target
    except OSError:
        return None
